SELECT o.id, o.order_no, o.user_id, o.seller_id, s.shop_name, o.total_amount, o.status, o.receiver_name, o.receiver_phone, o.receiver_address, o.logistics_company, o.logistics_no, o.shipped_at, o.received_at, o.created_at FROM orders o LEFT JOIN sellers s ON o.seller_id = s.id WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM orders
WHERE user_id = #{userId}

    AND status = #{status}

SELECT o.id, o.order_no, o.user_id, o.seller_id, o.total_amount, o.status, o.receiver_name, o.receiver_phone, o.receiver_address, o.logistics_company, o.logistics_no, o.shipped_at, o.received_at, o.created_at FROM orders o WHERE o.seller_id = #{sellerId}
AND o.status = #{status}
ORDER BY o.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM orders
WHERE seller_id = #{sellerId}

    AND status = #{status}
